import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { gradeOn, usePeople } from '../people/people';
import { useSettings } from '../roles/roles';
import { chargedOf, sumDue, useRates } from '../rates/rates';
import { countsLive, holdsOf, useClaims } from './claims';

// Per tag ever used on the sheet (by any of its claims, sorted), its due-total: the dues (with any late charge, as
// shown now, each at the grade its person had on its date) of the claims that count live and carry it now, added up,
// skipping n/a. A claim with two tags counts in both.
function TagTotals() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const claims = useClaims();
  const rates = useRates();
  const settings = useSettings();
  const today = useSheetToday();
  if (!user || !sheet) return null;
  const allClaims = claims.data ?? [];
  const personOf = new Map((people.data ?? []).map((p) => [p.id, p]));
  const held = holdsOf(people.data);
  const tags = [...new Set(allClaims.flatMap((c) => c.tagsUsed ?? []))].sort();
  return (
    <section data-testid="tag-totals">
      <h2>Tags</h2>
      <table>
        <thead>
          <tr>
            <th>Tag</th>
            <th>Due</th>
          </tr>
        </thead>
        <tbody>
          {tags.map((t) => (
            <tr key={t}>
              <td>{t}</td>
              <td data-testid={`tag-${t}-due-total`}>
                {sumDue(allClaims
                  .filter((c) => (c.tags ?? []).includes(t) && personOf.has(c.personId) && countsLive(c, held, today))
                  .map((c) => chargedOf(c, rates.data, gradeOn(personOf.get(c.personId)!, c.date), settings.data, today)))}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 34, Component: TagTotals });
import { useQuery } from '@tanstack/react-query';
import { useNavigate } from '@tanstack/react-router';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';
import type { Hold } from '../claims/claims';
import { asFlag, asString, useSearchParam } from '../../url/useSearchParam';

export const GRADES = ['A', 'B', 'C'] as const;

// `grade` is the grade in force on the sheet's today; `grades` every grade they were given with the date it
// applies from (null for the first, which applies from the beginning of time), by from-date.
// `version` is raised on every save; an edit sends the version it loaded and is refused (409) when
// someone else has saved the person since.
// `statementCount` is how many statements were taken for them; `statedTotal` and `statementDate` are the last
// one's due-total and the sheet's today when it was taken (null with none).
// `retiredFrom` is the date they are retired from (null: not retired); with one set they count as retired at
// once, whatever the date; from the day it is reached (the sheet's today on or after it) their OPEN and PENDING
// claims count in no live total, as a hold's would, unless a statement binds them.
// `held`: whether they have any hold. `holds`: their holds, earliest from-date first; their OPEN and PENDING
// claims dated within one count in no live total, unless a statement binds them; their other claims still count.
// `terms`: their own terms in days (null: none); a claim of theirs is due by its date plus these, ahead of their
// grade's terms and the sheet's.
// `contact`: their contact, trimmed and lower-cased (null: none); no two people on a sheet share one.
// `aliases`: other names they go by, sorted ignoring case; the quick-add bar and the paste box find them by one too.
// `clashing`: whether their name or an alias is in use on another sheet of the sheet's tree (its ancestors and
// descendants); an edit of them through the person form is refused until it leaves them no longer clashing.
// `origin`: the sheet they were transferred from (null: they were not transferred here).
// `retirements`: their past retirements, each ended by an unretire, earliest from-date first: from a date to the
// day they were unretired; a claim dated after the from and before the to is refused, as one after a retirement is.
// `patronIds`: the other people on the sheet they have named as patrons, in the order they were named.
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: DatedGrade[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retiredFrom: string | null;
  held: boolean;
  holds: Hold[];
  patronIds: number[];
  terms: number | null;
  contact: string | null;
  aliases: string[];
  clashing: boolean;
  origin: string | null;
  retirements: Retirement[];
};

/** A past retirement: from a date to the day they were unretired (YYYY-MM-DD). */
export type Retirement = { from: string; to: string };

/** A grade a person was given, from a date on (YYYY-MM-DD; null: from the beginning of time). */
export type DatedGrade = { grade: string; from: string | null };

/** The grade in force for a person on a date: the one whose from-date is the latest on or before it, the first
 *  grade they were given applying from the beginning of time. */
export function gradeOn(person: Person, date: string | undefined): string {
  if (date === undefined) return person.grade;
  let found = person.grade;
  for (const g of person.grades) {
    if (g.from === null || g.from <= date) found = g.grade;
  }
  return found;
}

export const peopleQueryKey = (sheetId: string) => ['sheet', sheetId, 'people'] as const;

export const peoplePath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/people`;

/** The sheet's people, in list order: by their place, which the move buttons swap; a new person goes to the end. */
export function usePeople() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: peopleQueryKey(sheet ?? ''),
    queryFn: () => getJson<Person[]>(peoplePath(sheet ?? '')),
    enabled: !!sheet,
  });
}

/** The id of the person whose editor is open (search param `editPerson`), or '' for none. */
/** The mutation key of a person form save; an editor is not opened while one is on its way, so it never loads
 *  the person from before the save (nor is closed by it). */
export const personSaveKey = ['person-save'] as const;

export const useEditingPerson = () => useSearchParam('editPerson', asString);

/** Whether retired people are listed (search param `showRetired`): off when the screen is first opened, and
 *  left as it is by loading a sheet. */
export const useShowRetired = () => useSearchParam('showRetired', asFlag);

const asIds = (raw: unknown): number[] =>
  raw === undefined || raw === null || raw === ''
    ? []
    : String(raw).split(',').map(Number).filter((n) => Number.isInteger(n));

/** The ids of the selected people (search param `selectedPeople`). */
export function useSelectedPeople() {
  const [ids] = useSearchParam('selectedPeople', asIds);
  const navigate = useNavigate();
  const update = (change: (ids: Set<number>) => void) =>
    void navigate({
      to: '.',
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        const set = new Set(asIds(prev.selectedPeople));
        change(set);
        if (set.size === 0) delete next.selectedPeople;
        else next.selectedPeople = [...set].join(',');
        return next;
      },
      replace: true,
    });
  return {
    selected: new Set(ids),
    toggle: (id: number, on: boolean) => update((set) => (on ? set.add(id) : set.delete(id))),
    clear: () => update((set) => set.clear()),
  };
}
import { useEffect, useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, getJson, postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { GRADES, personSaveKey, peoplePath, peopleQueryKey, usePeople, useEditingPerson, type Person } from './people';

// The person form: adds a person, or — while a person's editor is open — saves their changes. A save records the
// grade from the from-date (blank: the sheet's today), keeping the grades already recorded; the grade a person is
// added with applies from the beginning of time. A person's own terms (blank: none) come ahead of their grade's
// and the sheet's when a claim's due-by is fixed. A contact (blank: none) is kept trimmed and lower-cased and
// must not be another person's on the sheet. The
// editor remembers the version of the person it loaded; when someone else has saved them since, the
// save is refused and the form shows the person's current values (and version) instead. Any other refused save
// closes the editor, its error staying on the form until the form is next changed or submitted, an editor is
// opened or another sheet is loaded.
function PersonForm() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [editing] = useEditingPerson();
  const people = usePeople();
  const [refused, setRefused] = useState(false);
  useEffect(() => {
    if (editing) setRefused(false);
  }, [editing]);
  useEffect(() => setRefused(false), [sheet]);
  if (!user || !sheet) return null;
  const person = editing ? people.data?.find((p) => String(p.id) === editing) : undefined;
  // Keyed by who is being edited, so opening an editor fills the form with that person's values;
  // an editor for someone not on this sheet falls back to the add form.
  return <PersonFormFields key={`${sheet}:${person?.id ?? ''}`} sheet={sheet} person={person}
    people={people.data ?? []} refused={refused} setRefused={setRefused} />;
}

function PersonFormFields({ sheet, person, people, refused, setRefused }: {
  sheet: string;
  person?: Person;
  people: Person[];
  refused: boolean;
  setRefused: (refused: boolean) => void;
}) {
  const [user] = useCurrentUser();
  const [, setEditing] = useEditingPerson();
  const [name, setName] = useState(person?.name ?? '');
  const [grade, setGrade] = useState(person?.grade ?? 'A');
  const [gradeFrom, setGradeFrom] = useState('');
  const [terms, setTerms] = useState(person?.terms == null ? '' : String(person.terms));
  const [contact, setContact] = useState(person?.contact ?? '');
  const [version, setVersion] = useState(person?.version);
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationKey: personSaveKey,
    mutationFn: (body: { name: string; grade: string; gradeFrom: string; terms: string; contact: string }) =>
      person
        ? putJson<Person>(`${peoplePath(sheet)}/${person.id}`, { ...body, version }, user)
        : postJson<Person>(peoplePath(sheet), body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleQueryKey(sheet) });
      if (person) {
        setEditing(undefined);
      } else {
        setName('');
        setGrade('A');
        setGradeFrom('');
        setTerms('');
        setContact('');
      }
    },
    onError: async (error) => {
      if (!person) return;
      if (!(error instanceof HttpError) || error.status !== 409) {
        setRefused(true);
        setEditing(undefined);
        return;
      }
      const current = await queryClient.fetchQuery({
        queryKey: peopleQueryKey(sheet),
        queryFn: () => getJson<Person[]>(peoplePath(sheet)),
        staleTime: 0,
      });
      const now = current.find((p) => p.id === person.id);
      if (now) {
        setName(now.name);
        setGrade(now.grade);
        setTerms(now.terms == null ? '' : String(now.terms));
        setContact(now.contact ?? '');
        setVersion(now.version);
      }
    },
  });
  const submit = useSubmitOnce(save);
  const conflict = save.error instanceof HttpError && save.error.status === 409;

  return (
    <form
      data-testid="person-form"
      onSubmit={(e) => {
        e.preventDefault();
        setRefused(false);
        const given = contact.trim().toLowerCase();
        // Refused at once when another person on the sheet as loaded has the contact; the store checks again.
        if (given !== '' && people.some((p) => p.id !== person?.id && p.contact === given)) {
          save.reset();
          setRefused(true);
          if (person) setEditing(undefined);
          // what is shown may be stale: read the people again, as a refused save in the store would
          void queryClient.invalidateQueries({ queryKey: peopleQueryKey(sheet) });
          return;
        }
        submit({ name, grade, gradeFrom: gradeFrom.trim(), terms: terms.trim(), contact: contact.trim() });
      }}
    >
      <h2>{person ? 'Edit person' : 'Add a person'}</h2>
      <input
        data-testid="person-form-name"
        placeholder="Name"
        value={name}
        onChange={(e) => { setName(e.target.value); save.reset(); setRefused(false); }}
      />
      <select
        data-testid="person-form-grade"
        value={grade}
        onChange={(e) => { setGrade(e.target.value); save.reset(); setRefused(false); }}
      >
        {GRADES.map((g) => (
          <option key={g} value={g}>{g}</option>
        ))}
      </select>
      <input
        data-testid="person-form-grade-from"
        placeholder="Grade from (YYYY-MM-DD)"
        value={gradeFrom}
        onChange={(e) => { setGradeFrom(e.target.value); save.reset(); setRefused(false); }}
      />
      <input
        data-testid="person-form-terms"
        placeholder="Terms (days; blank for none)"
        value={terms}
        onChange={(e) => { setTerms(e.target.value); save.reset(); setRefused(false); }}
      />
      <input
        data-testid="person-form-contact"
        placeholder="Contact (blank for none)"
        value={contact}
        onChange={(e) => { setContact(e.target.value); save.reset(); setRefused(false); }}
      />
      <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
        {person ? 'Save' : 'Add person'}
      </button>
      {person && (
        <button type="button" data-testid="person-form-cancel" onClick={() => setEditing(undefined)}>
          Cancel
        </button>
      )}
      {(save.isError || refused) && (
        <span data-testid="person-form-error">
          {conflict
            ? 'Someone else has saved this person since you opened the editor; the form now shows their current values.'
            : 'A name is required and must not already be in use on this sheet, the grade must be A, B or C, the grade from-date must be a date, the terms must be a whole number of days or blank, and the contact must not be another person\'s on this sheet.'}
        </span>
      )}
    </form>
  );
}

export const contribution = HomeMain.fill({ order: 10, Component: PersonForm });
