  expect(await ui.addHoliday(pg_uma, "2026-03-13")).toBe(true);
  await ui.setSetting(pg_uma, "grace-C", "5");
  expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "0.40", "note": ""})).toBe(true);
  await ui.setSetting(pg_uma, "pot", "7.77");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00", "from": "2026-03-16", "to": "2026-03-25"})).toBe(true);
  expect(await ui.generatePeriods(pg_uma, "2026-02-01", "2026-04-30")).toBe(3);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "contact": "ADA@X", "tags": "b, a"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "terms": "20", "contact": "ben@x", "tags": "b, a"}));
  expect(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C", "contact": " Ada@x "})).toBeNull();
  expect(await ui.retire(pg_uma, p_ada, "2026-03-15")).toBe(true);
  await ui.showRetired(pg_uma, true);
  await ui.expectAuditView(pg_uma, "Ada", [
  ]);
  expect(await ui.setSettingDated(pg_uma, "clerk-limit", "1.50", "2026-04-02", "3.00")).toBe(true);
  expect(await ui.periodAction(pg_uma, "2026-04", "close")).toBe(true);
  expect(await ui.bulkGrade(pg_uma, [p_cam, p_ada], {"grade": "B"})).toBe(2);
  expect(await ui.addClaim(pg_uma, p_cam, {"amount": "1.00", "date": "2026-03-15", "tags": " c "})).toBeNull();
  expect(await ui.statementAsOf(pg_uma, p_ada, "2026-03-15")).toBe(false);
  await ui.refresh(pg_uma);
  expect(await ui.periodAction(pg_uma, "2026-03", "close")).toBe(true);
  expect(await ui.editPerson(pg_uma, p_cam, {"grade": "A"})).toBe(true);
  expect(await ui.watch(pg_uma, p_ada, true)).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  await ui.showRetired(pg_vic, true);
  expect(await ui.transfer(pg_vic, p_ada, `${sheet}-t`)).toBe(false);
  expect(await ui.addClaim(pg_vic, p_cam, {"amount": "0.04", "date": "2026-02-25", "note": "n"})).toBeNull();
  expect(await ui.addClaimTwice(pg_vic, p_ada, {"amount": "99.95", "date": "2026-02-10"})).toBeNull();
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_ada)).toHaveCount(0);
  await ui.showRetired(pg_wes, true);
  expect(await ui.addClaim(pg_wes, p_ada, {"amount": "1.00", "note": "n", "ref": "R-1", "tags": " c "})).toBeNull();
  expect(await ui.addClaim(pg_wes, p_ada, {"amount": "25.00"})).toBeNull();
  await ui.setAsOf(pg_wes, "2026-03-09");
  await ui.refresh(pg_wes);
