package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.hq.app.sheet.Sheet;

/** The person form's rules, shared by the form and the people import box. */
public final class PersonRules {

    private static final Set<String> GRADES = Set.of("A", "B", "C");

    private static final Pattern TERMS = Pattern.compile("\\d{1,5}");

    private PersonRules() {
    }

    /**
     * Checks the form's fields, trimming the name; refuses an empty name or a grade other than A, B or C, a grade
     * from-date that is not a calendar date, and terms that are not a whole number of days; the contact is trimmed
     * and lower-cased.
     */
    public static PersonRequest check(String name, String grade, Long version, String gradeFrom, String terms,
            String contact) throws InvalidPersonException {
        name = name == null ? "" : name.trim();
        grade = grade == null ? "" : grade.trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("A name is required.");
        }
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        gradeFrom = gradeFrom == null ? "" : gradeFrom.trim();
        if (!gradeFrom.isEmpty()) {
            try {
                LocalDate.parse(gradeFrom);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("Not a date: " + gradeFrom);
            }
        }
        terms = terms == null ? "" : terms.trim();
        if (!terms.isEmpty() && !TERMS.matcher(terms).matches()) {
            throw new InvalidPersonException("The terms must be a whole number of days, 0 or more, or blank.");
        }
        contact = contact == null ? "" : contact.trim().toLowerCase(Locale.ROOT);
        return new PersonRequest(name, grade, version, gradeFrom, terms, contact);
    }

    /**
     * Makes the person to add to the sheet, unsaved: refused when the name is a name or alias on the sheet or on
     * another sheet of its tree, ignoring case, or the contact is another person's on the sheet.
     */
    public static Person make(PersonRequest request, Sheet sheet, PersonRepository repository,
            PersonAliasRepository aliases, TreeNames tree) throws InvalidPersonException {
        if (repository.existsBySheetIdAndNameIgnoreCase(sheet.getId(), request.name())
                || aliases.existsBySheetIdAndAliasIgnoreCase(sheet.getId(), request.name())) {
            throw new InvalidPersonException("The name is already in use on this sheet.");
        }
        if (tree.usedAround(sheet.getId(), request.name())) {
            throw new InvalidPersonException("The name is already in use on a sheet of this sheet's tree.");
        }
        if (request.contactOrNull() != null
                && repository.existsBySheetIdAndContact(sheet.getId(), request.contactOrNull())) {
            throw new InvalidPersonException("The contact is already in use on this sheet.");
        }
        Person person = new Person(sheet.getId(), request.name(), request.grade());
        person.setAddedOn(sheet.getToday());
        person.setTerms(request.termsDays());
        person.setContact(request.contactOrNull());
        return person;
    }

    /** The PERSON_ADDED record for the added person: their terms when they have any, their contact when they have one. */
    public static String addedLine(Person person, String by) {
        return "PERSON_ADDED sheet=" + person.getSheetId() + " by=" + by
                + " name=" + person.getName() + " grade=" + person.getGrade()
                + (person.getTerms() == null ? "" : " terms=" + person.getTerms())
                + (person.getContact() == null ? "" : " contact=" + person.getContact());
    }

    /** The PERSON_EDITED record for the edited person, once saved, with the grade in force on the sheet's today, and
     *  their terms when the edit changed them (empty when cleared), and likewise their contact. */
    public static String editedLine(Person person, String grade, String by) {
        return "PERSON_EDITED sheet=" + person.getSheetId() + " by=" + by
                + " name=" + person.getName() + " grade=" + grade
                + (person.isTermsChanged() ? " terms=" + (person.getTerms() == null ? "" : person.getTerms()) : "")
                + (person.isContactChanged() ? " contact=" + (person.getContact() == null ? "" : person.getContact()) : "");
    }
}
package net.officefloor.hq.app.person;

/** The person form as submitted: a name and a grade, their own terms in days (blank: none), their contact (trimmed and lower-cased; blank: none), and for an edit the version of the person it loaded and the
 *  date the grade applies from (blank: the sheet's today). */
public record PersonRequest(String name, String grade, Long version, String gradeFrom, String terms,
        String contact) {

    /** The terms as a number of days; null when blank. */
    public Integer termsDays() {
        return terms == null || terms.isEmpty() ? null : Integer.valueOf(terms);
    }

    /** The contact; null when blank. */
    public String contactOrNull() {
        return contact == null || contact.isEmpty() ? null : contact;
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Reads the person form from the body, checked by {@link PersonRules#check}: the name trimmed, refusing an empty
 * name or a grade other than A, B or C, a grade from-date that is not a calendar date, and terms that are not a
 * whole number of days; the contact is trimmed and lower-cased.
 */
public class ValidatePerson {
    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body) throws InvalidPersonException {
        if (request == null) {
            throw new InvalidPersonException("A name is required.");
        }
        body.set(PersonRules.check(request.name(), request.grade(), request.version(), request.gradeFrom(),
                request.terms(), request.contact()));
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.EntityManager;
import jakarta.persistence.LockModeType;
import java.time.LocalDate;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.orm.ObjectOptimisticLockingFailureException;

/** Saves the person's name, terms and contact, and records their grade from the form's from-date (the sheet's today when blank),
 *  replacing the grade recorded for that date and keeping the others. */
public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person, @Val Sheet sheet, PersonRepository repository,
            PersonAliasRepository aliases, TreeNames tree,
            PersonGradeRepository grades, EntityManager entityManager)
            throws InvalidPersonException, PersonConflictException {
        if (request.version() == null || request.version() != person.getVersion()) {
            throw new PersonConflictException();
        }
        if (repository.existsBySheetIdAndNameIgnoreCaseAndIdNot(person.getSheetId(), request.name(), person.getId())
                || aliases.existsBySheetIdAndAliasIgnoreCase(person.getSheetId(), request.name())) {
            throw new InvalidPersonException("The name is already in use on this sheet.");
        }
        // A person clashing with the tree may be edited only to a name, with their aliases, that no longer clashes.
        java.util.List<String> names = new java.util.ArrayList<>(java.util.List.of(request.name()));
        aliases.findByPersonIdOrderByIdAsc(person.getId()).forEach(a -> names.add(a.getAlias()));
        if (tree.usedAround(person.getSheetId(), names)) {
            throw new InvalidPersonException("The name or an alias is already in use on a sheet of this sheet's tree.");
        }
        if (request.contactOrNull() != null && repository.existsBySheetIdAndContactAndIdNot(person.getSheetId(),
                request.contactOrNull(), person.getId())) {
            throw new InvalidPersonException("The contact is already in use on this sheet.");
        }
        LocalDate from = request.gradeFrom() == null || request.gradeFrom().isEmpty() ? sheet.getToday()
                : LocalDate.parse(request.gradeFrom());
        person.setName(request.name());
        person.setTerms(request.termsDays());
        person.setContact(request.contactOrNull());
        try {
            // Every save raises the version, even one that changes only a dated grade.
            entityManager.lock(person, LockModeType.OPTIMISTIC_FORCE_INCREMENT);
            repository.saveAndFlush(person);
        } catch (ObjectOptimisticLockingFailureException | jakarta.persistence.OptimisticLockException e) {
            // saved by someone else between the load and this save
            throw new PersonConflictException();
        }
        PersonGrade dated = grades.findByPersonIdAndFromDate(person.getId(), from)
                .orElseGet(() -> new PersonGrade(person.getSheetId(), person.getId(), request.grade(), from));
        dated.setGrade(request.grade());
        dated.setMadeOn(sheet.getToday());
        grades.saveAndFlush(dated);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.statement.Statement;

/** A person as the screen shows them: their grade in force on the sheet's today, and every grade they were given
 *  with its from-date (null for the first, which applies from the beginning of time), with their statement count
 *  and their last statement's due-total and date (null with none), and the date they are retired from (null: not
 *  retired), and whether they have any hold, and their holds (earliest first), and the ids of their patrons in the order they were named, and their own terms in days (null: none), and their contact (null: none), and their aliases, sorted ignoring case, and whether
 *  they clash: their name or an alias is in use on another sheet of the sheet's tree, and the sheet they were
 *  transferred from (null: none), and their past retirements (earliest first). */
public record PersonResponse(long id, String name, String grade, List<DatedGrade> grades, long version,
        int statementCount, String statedTotal, String statementDate, String retiredFrom, boolean held,
        List<Hold> holds, List<Long> patronIds, Integer terms,
        String contact, List<String> aliases, boolean clashing, String origin,
        List<Retirement> retirements) {

    /** A past retirement, from a date to the day they were unretired. */
    public record Retirement(String from, String to) {
    }

    /** A hold from a date on, to a date (inclusive; null: open-ended). */
    public record Hold(String from, String to) {
    }

    /** A grade from a date on (null: from the beginning of time). */
    public record DatedGrade(String grade, String from) {
    }

    /** @param statements the person's statements, oldest first.
     *  @param patrons the person's patrons, in the order they were named.
     *  @param grades the person's grades over time.
     *  @param aliases the person's aliases.
     *  @param today the sheet's today.
     *  @param usedAround the names and aliases, lower-cased, in use on the other sheets of the sheet's tree. */
    public static PersonResponse from(Person person, List<Statement> statements, List<Patron> patrons,
            List<PersonAlias> aliases, PersonGrades grades, LocalDate today,
            java.util.Set<String> usedAround) {
        Statement last = statements.isEmpty() ? null : statements.get(statements.size() - 1);
        List<DatedGrade> dated = new ArrayList<>();
        dated.add(new DatedGrade(grades.first(), null));
        grades.dated().forEach(g -> dated.add(new DatedGrade(g.getGrade(), g.getFromDate().toString())));
        return new PersonResponse(person.getId(), person.getName(), grades.on(today), dated, person.getVersion(),
                statements.size(), last == null ? null : last.getDueTotal(),
                last == null ? null : last.getTakenOn().toString(),
                person.getRetiredFrom() == null ? null : person.getRetiredFrom().toString(), person.isHeld(),
                person.getHolds().stream().map(h -> new Hold(h.getFromDate().toString(),
                        h.getToDate() == null ? null : h.getToDate().toString())).toList(),
                patrons.stream().map(Patron::getPatronId).toList(), person.getTerms(), person.getContact(),
                aliases.stream().map(PersonAlias::getAlias)
                        .sorted(String.CASE_INSENSITIVE_ORDER.thenComparing(java.util.Comparator.naturalOrder()))
                        .toList(),
                usedAround.contains(TreeNames.key(person.getName()))
                        || aliases.stream().anyMatch(a -> usedAround.contains(TreeNames.key(a.getAlias()))),
                person.getOriginSheet(),
                person.getRetirements().stream().map(r -> new Retirement(r.getFromDate().toString(),
                        r.getToDate().toString())).toList());
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import jakarta.persistence.Transient;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

/** A person on a sheet: a name and a grade (A, B or C), the date they are retired from (null: not retired),
 *  and their holds over time. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(nullable = false)
    private String name;

    @Column(nullable = false)
    private String grade;

    /** Their own terms in days (null: none): a claim of theirs is due by its date plus these, ahead of their
     *  grade's terms and the sheet's. */
    private Integer terms;

    /** Set by an edit that changed their terms, for its audit record; not stored. */
    @Transient
    private boolean termsChanged;

    /** Their contact, trimmed and lower-cased (null: none); no two people on a sheet share one. */
    private String contact;

    /** Set by an edit that changed their contact, for its audit record; not stored. */
    @Transient
    private boolean contactChanged;

    /** Their place in the sheet's list, lowest first (null: their id, which puts a person added later at the end). */
    private Long position;

    /** Raised on every save; an edit naming an older version is refused. */
    @Version
    @Column(nullable = false)
    private long version;
    }

    public String getOriginSheet() {
        return originSheet;
    }

    public void setOriginSheet(String originSheet) {
        this.originSheet = originSheet;
    }

    public String getContact() {
        return contact;
    }

    /** Sets their contact, noting whether it differs from the one they had. */
    public void setContact(String contact) {
        contactChanged = !java.util.Objects.equals(this.contact, contact);
        this.contact = contact;
    }

    public boolean isContactChanged() {
        return contactChanged;
    }

    public long getVersion() {
        return version;
    }

    public LocalDate getAddedOn() {
        return addedOn;
    }

    public void setAddedOn(LocalDate addedOn) {
        this.addedOn = addedOn;
    }

    /** Retires them from a date, the change made on the sheet's today given. */
    public void retire(LocalDate retiredFrom, LocalDate madeOn) {
        this.retiredFrom = retiredFrom;
        this.retiredMadeOn = madeOn;
    }

    /** Unretires them on the sheet's today given: their retirement is kept as a past one, from its date to that day. */
    public void unretire(LocalDate on) {
        retirements.add(new PersonRetirement(retiredFrom, on, retiredMadeOn, on));
        this.retiredFrom = null;
        this.retiredMadeOn = null;
    }

    /** A copy of them as they stood at the end of a date: only the holds and retirement made while the sheet's
     *  today was on or before it. Only worked out, never saved. */
    public Person asOf(LocalDate date) {
        Person then = new Person(sheetId, name, grade);
        then.id = id;
        then.position = position;
        then.terms = terms;
        then.contact = contact;
        then.addedOn = addedOn;
        if (retiredMadeOn == null || !retiredMadeOn.isAfter(date)) {
            then.retiredFrom = retiredFrom;
            then.retiredMadeOn = retiredMadeOn;
        }
        for (PersonRetirement r : retirements) {
            if (r.madeBy(date)) {
                then.retirements.add(r);
            } else if (r.retiredBy(date)) {
                then.retiredFrom = r.getFromDate();
                then.retiredMadeOn = r.getRetireMadeOn();
            }
        }
        holds.stream().filter(h -> h.madeBy(date)).forEach(then.holds::add);
        return then;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public List<PersonRetirement> getRetirements() {
        return retirements;
    }
package net.officefloor.hq.app.claim;

import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.TreeSet;

/** A claim's tags as stored: trimmed, lower-cased, without repeats, sorted and comma separated; null for none. */
public final class Tags {

    private Tags() {
    }

    /** The tags of a comma separated text (null: blank), as stored; null when it names none. */
    public static String normalise(String field) {
        if (field == null) {
            return null;
        }
        TreeSet<String> tags = new TreeSet<>();
        for (String t : field.split(",")) {
            String tag = t.trim().toLowerCase(Locale.ROOT);
            if (!tag.isEmpty()) {
                tags.add(tag);
            }
        }
        return tags.isEmpty() ? null : String.join(",", tags);
    }

    /** The stored tags (null: none) as a sorted list. */
    public static List<String> list(String stored) {
        return stored == null || stored.isEmpty() ? List.of() : Arrays.asList(stored.split(","));
    }
}

